function appendCalibrationFeedback(){const a=calibrationRecord();if(!a&&!calibrationOn)return;const body=$('sheet').querySelector('.dialog-body');if(!body)return;body.insertAdjacentHTML('beforeend','<aside class="calibration-result"><strong>Test capture</strong><p>'+(a?(calibrationSaved?'Saved on this device.':'Session only · export before leaving.'):(calibrationMessage||'This attempt was not captured. Start a fresh sample.'))+'</p>'+(a?'<p class="calibration-flag-status">'+(a.feedback?'Feedback flagged: '+esc(a.feedback.flag):'Tester label: unlabelled')+'</p><button class="textbtn" data-action="calibration-flag">This feedback feels wrong</button>':'')+'</aside>');}
function calibrationFlagPanel(){const a=calibrationRecord();if(!a)return;openSheet('Flag this feedback','<p>The engine said this attempt '+(a.evaluation.qualified?'passed':'needs another try')+'. What did you expect?</p><div class="stack"><button class="btn secondary" data-action="calibration-label" data-id="should-pass">It should have passed</button><button class="btn secondary" data-action="calibration-label" data-id="should-fail">It should have failed</button><button class="btn secondary" data-action="calibration-label" data-id="unclear">The feedback is unclear</button></div><p class="small">This records your opinion for review. It does not change the score or approve the teaching model.</p>');}
function labelCalibration(flag){const a=calibrationRecord();if(!a||!['should-pass','should-fail','unclear'].includes(flag))return;a.feedback={flag,reportedAt:new Date().toISOString(),source:'tester-reported'};a.testerAssessment=flag==='should-pass'?'looks-correct':flag==='should-fail'?'looks-wrong':'unsure';persistCalibration();toast('Your feedback flag is saved'+(calibrationSaved?' locally.':' for this session.'));closeSheet();if(current.calibrationOnly)calibrationResultSheet();else resultSheet();}
function exportCalibration(){const pack={format:'harf-calibration',schemaVersion:1,appVersion:'5.2',exportedAt:new Date().toISOString(),contains:'recorded-pointer-input',reviewStatus:'unreviewed',notes:['No samples are expert-labelled by default.','Tester intention/assessment is distinct from reviewer ground truth.','Coordinates are logical 1000×1000; display metadata records the capture scale.','A stroke at the point cap may be truncated; check sampling.anyStrokeAtCap.','Each stroke captureContext records its actual display scale at pointer-down.','Optional device fields are browser-reported; normalized scoring coordinates/pressure are unchanged.'],records:structuredClone(calibrationRows)};if(calibrationLoadIssue)try{pack.unparsedLocalCaptureStore=localStorage.getItem(CALIBRATION_KEY);}catch{}download(new Blob([JSON.stringify(pack,null,2)],{type:'application/json'}),'Khatti-Calibration-'+new Date().toISOString().slice(0,10)+'.json');toast('Calibration pack downloaded. Clear captures only after keeping your exported file.');}
function clearCalibration(){try{localStorage.removeItem(CALIBRATION_KEY);}catch{toast('Could not clear saved test captures.');return;}calibrationRows=[];calibrationOn=false;calibrationSaved=true;calibrationLoadIssue=false;calibrationMessage='Test captures cleared. Your practice gallery and progress are unchanged.';closeSheet();render();calibrationPanel();}
function calibrationResultSheet(){if(!ink.length)return;lastResult=E.evaluate(ink,current,inputType);captureCalibrationAttempt(lastResult);const r=lastResult,pts=[...current.strokes,...ink].flatMap(st=>st.points),reviewBounds={minX:Math.min(...pts.map(p=>p.x))-45,maxX:Math.max(...pts.map(p=>p.x))+45,minY:Math.min(...pts.map(p=>p.y))-45,maxY:Math.max(...pts.map(p=>p.y))+45};openSheet('Test sample result','<div class="guided-result"><h2>'+esc(current.title.en)+'</h2><p>'+(r.qualified?'Engine result: passed.':'Engine result: try again. '+t(r.reason))+'</p><button class="textbtn" data-action="compare-overlay">Compare overlay</button><div class="comparison"><div><canvas id="model-result" width="350" height="300"></canvas><span>Model</span></div><div><canvas id="user-result" width="350" height="300"></canvas><span>Your sample</span></div></div><p class="small">Comparison enlarged for review; the capture scale is unchanged.</p><button class="btn wide" data-action="result-next" data-id="retry">Try another sample</button><button class="textbtn" data-action="calibration-panel">Other test targets / export</button></div>');renderArtwork($('model-result'),{lessonId:current.id,strokes:[],reviewBounds},true);renderArtwork($('user-result'),{lessonId:current.id,strokes:ink,reviewBounds});appendCalibrationFeedback();}

function brand(){return '<div class="brand"><svg class="brandmark" viewBox="0 0 40 48" fill="none" aria-hidden="true"><path d="M6 42V22C6 13 14 9 20 3c6 6 14 10 14 19v20H6Z" stroke="currentColor" stroke-width="2.4"/><path d="M13 36V23c0-5 4-8 7-11 3 3 7 6 7 11v13" stroke="currentColor" stroke-width="2"/><path d="M20 25v13m-5-4 5 4 5-4" stroke="currentColor" stroke-width="2"/></svg><span class="header-lockup"><strong>Khatti</strong><span class="header-by"> · by QariAI</span></span></div>';}
function topActions(){return '<div class="top-actions"><button class="iconbtn theme-control" data-action="theme" aria-label="'+(settings.dark?'Light mode':'Dark mode')+'">'+icon(settings.dark?'sun':'moon')+'</button></div>';}
function nav(){return '<button class="navbtn" data-action="creative-studio" aria-current="false">'+icon('spark')+'Create</button>'+[['home','home','studio'],['gallery','gallery','practice'],['about','info','about']].map(([id,ico,label])=>'<button class="navbtn '+((screen===id||['course','journey','words','chapter3','loop'].includes(screen)&&id==='home')?'active':'')+'" aria-current="'+((screen===id||['course','journey','words','chapter3','loop'].includes(screen)&&id==='home')?'page':'false')+'" data-action="nav" data-id="'+id+'">'+icon(ico)+({home:'Learn',gallery:'Practice',about:'About'}[id])+'</button>').join('');}
function shell(body){return '<div class="shell"><aside class="sidebar">'+brand()+'<nav class="sidenav" aria-label="Studio">'+nav()+'</nav><div class="sidebar-note">'+icon('leaf')+'<p>'+t('gentle')+'</p><p class="small">Standalone · v6.54.0</p></div></aside><main class="main"><header class="topbar"><div class="mobilebrand">'+brand()+'</div><div class="top-title">Khatti · by QariAI</div>'+topActions()+'</header>'+body+'</main><nav class="bottomnav" aria-label="Studio">'+nav()+'</nav></div>';}
function note(){return '<div class="prototype-note">'+icon('info')+'<span>'+(screen==='practice'&&current.journey?reviewNote(current):t('protonote'))+'</span></div>';}
function pathSvg(l,cls=''){const commands=[];for(const s of l.strokes){let prev=E.hull(nibCorners(s.points[0],{...l.pen,...s.pen}));commands.push('M '+prev.map(p=>p.x.toFixed(1)+' '+p.y.toFixed(1)).join(' L ')+' Z');for(let i=1;i<s.points.length;i++){const next=nibCorners(s.points[i],{...l.pen,...s.pen}),h=E.hull(prev.concat(next));commands.push('M '+h.map(p=>p.x.toFixed(1)+' '+p.y.toFixed(1)).join(' L ')+' Z');prev=next;}}return '<svg class="'+cls+'" viewBox="100 100 800 800" fill="currentColor" aria-hidden="true"><path d="'+commands.join(' ')+'"/></svg>';}

function journeyView(){const course=activeStudy(),list=course.lessons,done=list.filter(lessonPractised).length,next=list.find(l=>!lessonPractised(l))||list[0];return shell('<button class="textbtn" data-action="nav" data-id="home">'+icon('back')+t('studio')+'</button><div class="journey-intro"><div><span class="pill green">'+t('naskh')+' · '+reviewLabel(list[0])+'</span><h1>'+t(course.title)+'</h1><p>'+t(course.sub)+'</p><div class="source-line">'+sourceCaption(list[0])+'<br>'+t('wordReference')+' · Noto Naskh Arabic</div></div><bdi dir="rtl" class="qword" lang="ar">'+course.text+'</bdi></div><div class="journey-title-row"><h2>'+t(course.steps)+'</h2><div class="journey-progress"><span>'+done+' / '+list.length+' '+t('journeyComplete')+'</span><div class="progressbar" role="progressbar" aria-label="Lesson steps practised" aria-valuemin="0" aria-valuemax="'+list.length+'" aria-valuenow="'+done+'"><span style="width:'+done/list.length*100+'%"></span></div></div></div><div class="journey-overview"><span>'+t('buildingBody')+'</span><span class="tiny-dot"></span><span>'+t(course.id==='allah'?'addingVowels':'addingMarks')+'</span><span class="tiny-dot"></span><span>'+t('completeWord')+'</span></div><div class="journeygrid">'+list.map((l,i)=>{const pr=progress[l.id],finished=pr?.qualifiedModes&&Object.values(pr.qualifiedModes).some(Boolean);return '<button class="journeycard '+(l===next?'next-step':'')+'" '+(l===next?'aria-current="step" ':'')+'data-action="lesson" data-id="'+l.id+'"><div class="stage-preview">'+pathSvg(l)+'</div><div class="stage-index"><span class="number '+(finished?'finished':'')+'">'+(finished?'✓':i+1)+'</span><span>'+t('naskh')+'</span></div><h3>'+t(l.labelKey)+'</h3><p>'+esc(txt(l.goal))+'</p><div class="stage-bottom"><span>'+(l===next?(done===list.length?'Practise again':pr?.attempts?'Continue practice':'Start practice'):t(finished?'stepComplete':pr?.attempts?'stepTried':'ready'))+'</span>'+icon('arrow')+'</div></button>';}).join('')+'</div><div class="review-note">'+icon(reviewed(list[0])?'check':'info')+'<span>'+reviewNote(list[0])+'</span></div><button class="textbtn status-help" data-action="practice-status-help">'+icon('info')+'About progress & model review</button><div class="row" style="flex-wrap:wrap"><button class="textbtn" data-action="word-notes">'+icon('eye')+t('inspectWord')+'</button><button class="textbtn" data-action="preview-piece">'+icon('gallery')+t('previewPiece')+'</button><button class="textbtn" data-action="review-notes">'+icon('info')+t('reviewSource')+'</button></div>'+basmalaPath()+'<div class="journal-link"><div><h3>'+t('foundationsLink')+'</h3><p>'+t('foundationsSub')+'</p></div><button class="textbtn" data-action="nav" data-id="course">'+t('foundationsOpen')+icon('arrow')+'</button></div>');}
function course(){return shell('<button class="textbtn" data-action="nav" data-id="home">'+icon('back')+t('scripts')+'</button><div class="coursehero"><div><span class="pill green">Stage 1 · Naskh</span><h1 style="margin-top:12px">Letters & strokes</h1><p>Begin with the dot and basic movements, then practise the available letters and a first connection.</p><span class="small muted">'+FOUNDATIONS.length+' '+t('lessons')+' · '+t('foundation')+' → '+t('connections')+'</span></div>'+pathSvg(LESSONS[7],'courseart')+'</div>'+['foundation','letters','connections'].map(stage=>'<div class="stagehead">'+t(stage)+'</div><div class="lessonlist">'+FOUNDATIONS.filter(l=>l.stage===stage).map(l=>'<button class="lessonrow" data-action="lesson" data-id="'+l.id+'"><div class="lessonpreview">'+pathSvg(l)+'</div><div><h3>'+esc(txt(l.title))+'</h3><p>'+strokeCount(l.strokes.length)+' · 2–4 '+'min'+'</p></div><span class="lessonstatus"><span class="statusword">'+t(progress[l.id]?.attempts?'done':'ready')+'</span>'+icon(progress[l.id]?.attempts?'check':'chevron')+'</span></button>').join('')+'</div>').join('')+'<div class="journal-link"><div><h3>'+t('journey')+'</h3><p>'+t('journeySteps')+'</p></div><button class="textbtn" data-action="nav" data-id="journey">'+t('journeyReady')+icon('arrow')+'</button></div>'+note());}
function galleryView(){return shell('<button class="btn secondary wide collection-entry" data-action="ayah-collection">My calligraphy collection →</button><div class="intro"><div><div class="eyebrow">'+t('private')+'</div><h1>'+t('practice')+'</h1><p>'+t('gallerynote')+'</p></div><button class="btn secondary" data-action="nav" data-id="course">'+t('trynew')+icon('pen')+'</button></div>'+(gallery.length?'<div class="gallerygrid">'+gallery.map((a,i)=>'<article class="gallerycard"><div class="thumb"><canvas data-art-index="'+i+'" width="500" height="320" aria-label="'+t('artwork')+'"></canvas></div><div class="meta"><h3>'+esc(txt(LESSONS.find(l=>l.id===a.lessonId).title))+'</h3><div class="small muted">'+t(a.mode)+(a.piece?' · '+t('pieceTag'):'')+' · '+new Date(a.date).toLocaleDateString('en-GB')+'</div><div class="row"><button class="textbtn" data-action="export-art" data-index="'+i+'">'+icon('download')+t('export')+'</button><button class="textbtn" data-action="gallery-svg" data-index="'+i+'">SVG</button><button class="iconbtn" data-action="delete-art" data-index="'+i+'" aria-label="'+t('delete')+'">'+icon('trash')+'</button></div></div></article>').join('')+'</div>':'<div class="empty"><div class="disc">'+icon('pen')+'</div><h2>'+t('empty')+'</h2><p>'+t('emptysub')+'</p><button class="btn" data-action="nav" data-id="course">'+t('begin')+icon('arrow')+'</button></div>'));}
function aboutView(){return shell('<div class="coursehero" style="grid-template-columns:1fr"><div><div class="eyebrow">Standalone · v6.54.0</div><h1 style="margin-top:13px">'+t('abouttitle')+'</h1><p>'+t('aboutsub')+'</p><button class="btn" data-action="nav" data-id="course">'+t('begin')+icon('arrow')+'</button></div></div><div class="insight"><h2>'+t('about')+'</h2><div class="about-actions"><button class="textbtn" data-studio-intro="library">Replay introduction</button><button class="textbtn" data-progress-transfer>Export / import progress</button></div><p>Drawing requires a finger, stylus or mouse; keyboard and screen-reader users can navigate and manage work, but cannot perform equivalent tracing. Palm filtering is best-effort: touch only after the pen is lifted for 1s.</p><ul class="about-list">'+[1,2,3,4,5].map(i=>'<li>'+t('about'+i)+'</li>').join('')+'</ul><div class="divider"></div><button class="textbtn" data-action="calibration-panel">'+icon('sliders')+'Local Test mode</button><button class="textbtn" data-action="download-tests">'+icon('download')+'Download synthetic regression tests</button><button class="textbtn" data-action="download-lesson">'+icon('download')+t('downloadlesson')+'</button><button class="textbtn" data-action="review-notes">'+icon('info')+t('reviewSource')+'</button><button class="textbtn" data-action="font-notes">'+icon('pen')+t('fontCredits')+'</button><button class="textbtn" data-action="device">'+icon('eye')+t('device')+'</button><button class="textbtn" data-action="delete-all">'+icon('trash')+t('deleteall')+'</button></div>');}
function wordContextHeader(){if(mode==='recall'&&!reveal)return '<div class="context-header recall-hidden"><div>'+icon('eye')+'</div><p>'+t('referenceHidden')+'<br>'+t(current.contextStrokes?'markScaffold':'referenceHiddenSub')+'</p></div>';return '<div class="context-header"><bdi dir="rtl" class="qword" lang="ar">'+current.source.text+'</bdi><span class="q-separator"></span><div><p>'+sourceCaption(current)+'</p><p>'+(current.lessonNote&&current.lessonNote!=='wordNote'?t(current.lessonNote):reviewLabel(current))+'</p></div><button class="iconbtn" data-action="word-notes" aria-label="'+t('inspectWord')+'">'+icon('eye')+'</button></div>';}

const u=text=>text;
let replaceIndex=null,undoActions=[],redoActions=[];
function initHistory(){replaceIndex=null;undoActions=ink.map(stroke=>({kind:'append',stroke}));redoActions=redo.map(stroke=>({kind:'append',stroke}));}
function finishEdit(){redo=redoActions.map(a=>a.stroke);feedReason='';attemptSaved=false;attemptToken=uuid();inkCache=null;saveDraft();updatePractice();requestDraw();}
function undoInk(){if(replaceIndex!==null){replaceIndex=null;inkCache=null;updatePractice();requestDraw();return;}const a=undoActions.pop();if(!a)return;if(a.kind==='replace')ink[a.index]=a.old;else ink.pop();redoActions.push(a);finishEdit();}
function redoInk(){replaceIndex=null;const a=redoActions.pop();if(!a)return;if(a.kind==='replace')ink[a.index]=a.stroke;else ink.push(a.stroke);undoActions.push(a);finishEdit();}
function strokeRetrySheet(){if(!ink.length)return;openSheet('Retry one stroke','<p>'+u('Choose a stroke to redraw. Your other strokes stay in place.')+'</p><div class="stroke-picker">'+ink.map((st,i)=>'<button class="stroke-choice" data-action="retry-stroke" data-id="'+i+'">'+inkSvg([st],{thumbnail:true})+'<span>'+u('Stroke')+' '+(i+1)+'</span></button>').join('')+'</div>');}
function beginStrokeRetry(i){if(!Number.isInteger(i)||!ink[i])return;closeSheet();replaceIndex=i;inkCache=null;updatePractice();requestDraw();toast(u('Redraw the selected stroke. Your other strokes are kept.'));}
function pulseStroke(){const paper=document.querySelector('.paper');if(!paper)return;paper.classList.remove('stroke-success');void paper.offsetWidth;paper.classList.add('stroke-success');clearTimeout(pulseStroke.timer);pulseStroke.timer=setTimeout(()=>paper.classList.remove('stroke-success'),480);}
function inkSvg(strokes,{thumbnail=false,paper='cream',frame=false}={}){const colors={cream:'#faf7ef',white:'#ffffff',night:'#13241d'},inkColor=paper==='night'?'#edf5ee':null;const pts=strokes.flatMap(st=>st.points.map(p=>({x:p.x,y:p.y,pad:st.nib.width})));const minX=pts.length?Math.min(...pts.map(p=>p.x-p.pad)):0,maxX=pts.length?Math.max(...pts.map(p=>p.x+p.pad)):1000,minY=pts.length?Math.min(...pts.map(p=>p.y-p.pad)):0,maxY=pts.length?Math.max(...pts.map(p=>p.y+p.pad)):1000;const dx=Math.max(1,maxX-minX),dy=Math.max(1,maxY-minY),pad=Math.max(dx,dy)*.07,bx=minX-pad,by=minY-pad,bw=dx+pad*2,bh=dy+pad*2;const f=n=>Number(n.toFixed(3)),poly=p=>'M '+p.map(q=>f(q.x)+' '+f(q.y)).join(' L ')+' Z';let shapes='';for(const st of strokes){const p=st.points,n=st.nib,col=inkColor||st.color||'#263c34';if(n.type==='round'){const width=n.width*.45;shapes+=p.length===1?'<circle cx="'+f(p[0].x)+'" cy="'+f(p[0].y)+'" r="'+f(width/2)+'" fill="'+col+'"/>':'<path d="M '+p.map(q=>f(q.x)+' '+f(q.y)).join(' L ')+'" fill="none" stroke="'+col+'" stroke-width="'+f(width)+'" stroke-linecap="round" stroke-linejoin="round"/>';}else{let d=poly(E.hull(nibCorners(p[0],n)));for(let i=1;i<p.length;i++)d+=' '+poly(E.hull(nibCorners(p[i-1],n).concat(nibCorners(p[i],n))));shapes+='<path d="'+d+'" fill="'+col+'"/>';}}return '<svg xmlns="http://www.w3.org/2000/svg" viewBox="'+[bx,by,bw,bh].map(f).join(' ')+'"'+(thumbnail?' aria-hidden="true"':' role="img"')+'><title>Khatti — handwritten practice</title><desc>Vector paths of the learner’s ink. No tracing guide or typeset reference.</desc>'+(!thumbnail?'<rect x="'+f(bx)+'" y="'+f(by)+'" width="'+f(bw)+'" height="'+f(bh)+'" fill="'+colors[paper]+'"/>':'')+shapes+(frame&&!thumbnail?'<rect x="'+f(bx+pad*.4)+'" y="'+f(by+pad*.4)+'" width="'+f(bw-pad*.8)+'" height="'+f(bh-pad*.8)+'" fill="none" stroke="#95af9c" stroke-width="'+f(Math.max(dx,dy)*.0015)+'"/>':'')+'</svg>';}
function exportSvg(a,style={}){if(!a?.strokes?.length){toast(u('Add some writing first.'));return;}download(new Blob([inkSvg(a.strokes,style)],{type:'image/svg+xml;charset=utf-8'}),'Khatti-'+a.lessonId+'-Writing.svg');toast(t('downloaded'));}
let referenceFontLoaded=false;
const referenceFontPromise=document.fonts.load('40px HarfNaskh','بسم').then(faces=>{referenceFontLoaded=faces.length>0;if(referenceFontLoaded){for(const [c,paint]of previewPaints)if(c.isConnected)paint();}return referenceFontLoaded;}).catch(()=>false);
async function fontForExport(){let timer;const ready=await Promise.race([referenceFontPromise,new Promise(resolve=>{timer=setTimeout(()=>resolve(false),3000);})]);clearTimeout(timer);if(!ready)toast(u('The Arabic reference font is still loading. Try PNG again shortly, or export SVG.'));return ready;}

