function guidedList(){return studyFor(current).lessons;}
function guidedPosition(){if(current.calibrationOnly)return{index:0,total:1};const list=guidedList();return {index:list.indexOf(current),total:list.length};}
function lessonPractised(l){return ['trace','copy','recall'].some(m=>progress[l.id]?.qualifiedModes?.[m]===true);}
function nextGuidedLesson(){const cursor=read('guidedCursor',null),saved=LESSONS.find(l=>l.id===cursor?.lessonId&&l.journey&&!l.calibrationOnly);if(saved&&!progress[saved.id]?.qualifiedModes?.[cursor.mode])return saved;return Q_LESSONS.find(l=>!lessonPractised(l))||ALLAH_LESSONS.find(l=>!lessonPractised(l))||ALLAH_LESSONS.at(-1);}
function resumeGuided(){const lesson=nextGuidedLesson(),cursor=read('guidedCursor',null),resume=cursor?.lessonId===lesson.id&&['trace','copy','recall'].includes(cursor.mode)?cursor.mode:'watch';openLesson(lesson.id);if(resume!=='watch')switchMode(resume);}
function practiceStatusHelp(){openSheet('Your progress & model review','<div class="status-explainer"><section><h3>Your practice</h3><p>Not attempted yet means you have not checked a sample for this step. Practice started means you have checked an attempt. Practised means an attempt met the shape and movement checks in tracing, copying or recall. Tracing is guided practice, not independent mastery.</p></section><section><h3>The teaching model</h3><p>Model review pending means the authored calligraphy is awaiting a named teacher’s written sign-off. It does not describe your attempt, and checking your writing does not submit it to a teacher.</p></section><section><h3>Saved on this device</h3><p>Completed strokes save automatically when storage is available. Continue practising restores your lesson and practice mode. Work stays in this browser; clearing browser data removes it. Export work you want to keep.</p></section></div><button class="btn wide" style="margin-top:16px" data-action="close">Got it</button>');}
function continuePractice(){const a=read('lastActivity',null),l=LESSONS.find(l=>l.id===a?.lessonId&&!l.calibrationOnly);if(a?.type==='movement'&&l){const m=a.mode;openLesson(l.id);if(['trace','copy','recall'].includes(m))switchMode(m);return;}if(a?.type==='ayah'||window.HarfAyahStudio.summary().hasCursor){window.HarfAyahStudio.resumePractice();return;}const old=LESSONS.find(l=>l.id===read('lastLesson',null)&&!l.calibrationOnly);openLesson(old?.id||FOUNDATIONS[0].id);}
function wordsView(){return shell('<button class="textbtn" data-action="nav" data-id="home">'+icon('back')+'Home</button><div class="learning-intro"><span class="eyebrow">STAGE 2 · WORDS</span><h1>Bring the letters together</h1><p>Follow authored movements for Bism and Allah, or practise 87 Qur’anic words with typeset guides.</p></div><section aria-label="Authored word movement studies"><h2 class="learning-section-title">Learn the movements</h2><div class="word-study-grid">'+['bism','allah'].map(id=>'<button class="word-study" data-action="study" data-id="'+id+'"><bdi class="qword" dir="rtl" lang="ar">'+STUDIES[id].text+'</bdi><h3>'+STUDIES[id].name+'</h3><p>'+STUDIES[id].lessons.length+' movement studies · review pending</p><span>Open movement lessons '+icon('arrow')+'</span></button>').join('')+'</div></section><section class="word-typeset"><h2>Practise more Qur’anic words</h2><p>87 word lessons across Al-Fatihah, Al-Ikhlas, Al-Falaq and An-Nas. Trace, copy and self-check the letters and marks.</p><button class="btn" data-action="word-library">Browse word practice'+icon('arrow')+'</button><p class="small muted">Typeset guides · learner self-checks · teacher review pending</p></section>');}
function home(){const hasActivity=!!read('lastActivity',null);return shell('<div class="mobile-home"><button class="textbtn" data-action="creative-studio">← Creative Studio</button><section class="learning-resume"><div><strong>'+(hasActivity?'Continue where you left off':'Your first guided study')+'</strong><p>'+(hasActivity?'Resume your last guided study.':'Begin with the first stroke, at your own pace.')+'</p></div><button class="btn" data-action="learning-continue">'+(hasActivity?'Continue practice →':'Start first lesson →')+'</button></section><h1 class="sr-only">Learn</h1><section aria-label="Pilot chapter" class="ch3-hero-wrap">'+ch3.hero()+'</section><section aria-label="Guided lesson paths"><div class="learning-path"><button class="learning-stage" data-action="nav" data-id="course"><span class="stage-number">1</span><div><h3>Letters & strokes</h3><p>Dots, basic strokes, Alif, Ba, Nun, Lam and connections.</p><span class="small muted">9 foundation activities</span></div>'+icon('arrow')+'</button><button class="learning-stage" data-action="nav" data-id="words"><span class="stage-number">2</span><div><h3>Words</h3><p>Learn connected movements, then practise Qur’anic words.</p><span class="small muted">Movement studies + 87 word lessons</span></div>'+icon('arrow')+'</button><button class="learning-stage" data-action="ayah-library"><span class="stage-number">3</span><div><h3>Complete ayahs</h3><p>Bring the words together on a complete writing page.</p><span class="small muted">22 ayahs across 4 surahs</span></div>'+icon('arrow')+'</button></div></section></div>');}
function practiceView(){return current.journey?guidedPracticeView():studioPracticeView();}
function guidedPracticeView(){const {index,total}=guidedPosition(),watch=mode==='watch',title=watch?'Watch the movement':mode==='trace'?'Your turn to trace':mode==='copy'?'Copy without the outline':'Write from memory',instruction=current.calibrationOnly?(current.id==='cal-bism'?'Write the complete word at its original lesson size, then check it.':'Trace one mark at its original lesson size, then check it.'):watch?'Follow the pen, then try tracing.':mode==='trace'?'Start at 1 and follow the arrows. Lift your pen between strokes.':mode==='copy'?'Use the small example, then write on the blank page.':'The example is hidden. Take your time.',specimen=mode==='copy'||mode==='recall'&&reveal;return '<main data-mode="'+mode+'" class="guided-shell"><header class="guided-header"><button class="iconbtn" data-action="exit" aria-label="Save and return home">'+icon('back')+'</button><div><h1>'+t(current.labelKey)+'</h1><p>Naskh · '+(reviewed(current)?'Reviewed model':'Movement study · review pending')+'</p></div><button class="iconbtn" data-action="guided-tools" aria-label="Tools and practice options">'+icon('more')+'</button></header><div class="guided-progress" id="lesson-progress"><span>Step '+(index+1)+' of '+total+'</span><div class="progressbar"><span style="width:'+(index+1)/total*100+'%"></span></div><span>'+t(mode)+'</span></div><section class="guided-instruction"><h2 tabindex="-1" aria-describedby="lesson-progress">'+title+'</h2><p>'+instruction+'</p></section><section class="guided-paper-area"><div class="canvas-label"><span id="stroke-label">'+strokeLabel()+'</span><span id="movement-name" class="current-stroke-name"></span></div>'+(specimen?'<div class="specimen-strip">'+pathSvg(current)+'<p>Example · '+t(current.labelKey)+'</p></div>':'')+'<div class="paper"><canvas id="writing-canvas" tabindex="0" role="img" aria-describedby="writing-help" aria-label="Writing canvas. '+esc(instruction)+'"></canvas><span id="writing-help" class="sr-only">Draw using a finger, stylus, or mouse. Tab reaches practice controls. Control or Command Z undoes a stroke; Shift Z redoes it.</span><span class="paper-caption">'+(watch?'WATCH THE PEN':mode==='trace'?'FOLLOW THE GUIDE':'YOUR PRACTICE PAGE')+'</span></div></section><div id="feedback-line" class="feedbackline" role="status" aria-live="polite" aria-atomic="true">'+icon('pen')+'<span>'+t(feedReason||(watch?'watchtip':'drawing'))+'</span></div>'+(watch?'<div class="watch-actions"><button class="iconbtn" id="play-toggle" data-action="play" aria-label="'+t(anim.playing?'pause':'play')+'">'+icon(anim.playing?'pause':'play')+'</button><button class="textbtn" data-action="guided-replay" aria-label="Replay demonstration">'+icon('replay')+'</button><button class="btn" data-action="mode" data-id="trace">I’m ready to trace'+icon('arrow')+'</button></div>':'<footer class="guided-footer"><div class="toolbar" role="toolbar" aria-label="Writing tools"><button class="toolbtn" id="undo-btn" data-action="undo" '+(!ink.length?'disabled':'')+'>'+icon('undo')+'Undo</button><button class="toolbtn" data-action="guided-replay">'+icon('replay')+'Replay</button><button class="toolbtn" data-action="guided-tools">'+icon('sliders')+'Tools</button></div><button class="btn" id="check-btn" data-action="check" '+(!ink.length?'disabled':'')+'>Check my writing'+icon('check')+'</button></footer>')+'<p id="save-status" class="guided-save">'+(current.calibrationOnly?'Sample is captured when you check it.':watch?'Watch first. Tracing opens when the demonstration ends.':t(storageOK?'saved':'unsaved'))+'</p></main>';}
function guidedTools(){openSheet('Practice tools','<div class="stack"><button class="textbtn" data-action="retry-strokes" '+(!ink.length||mode==='watch'?'disabled':'')+'>'+u('Retry one stroke')+'</button>'+(replaceIndex!==null?'<button class="textbtn" data-action="cancel-retry">'+u('Cancel stroke retry')+'</button>':'')+'<button class="textbtn" data-action="export-svg" '+(!ink.length?'disabled':'')+'>'+u('Export SVG · writing only')+'</button></div>'+'<div class="guided-tools"><button data-action="pen">'+icon('pen')+'Pen & ink</button><button data-action="guides">'+icon('sliders')+'Guides</button><button data-action="redo" '+(!redo.length?'disabled':'')+'>'+icon('redo')+'Redo</button><button data-action="guided-replay">'+icon('replay')+'Watch again</button></div><div class="divider"></div><details><summary style="min-height:48px;cursor:pointer">More practice options</summary><div class="stack"><button class="textbtn" data-action="guided-mode" data-id="trace">Guided tracing</button><button class="textbtn" data-action="guided-mode" data-id="copy">Copy the example</button><button class="textbtn" data-action="guided-mode" data-id="recall">Write from memory</button><button class="textbtn" data-action="more">Accessibility & settings</button><button class="textbtn" data-action="calibration-panel">Local Test mode</button><button class="textbtn" data-action="word-notes">Word & model reference</button><button class="textbtn" data-action="clear">Clear this page</button></div></details>');}
function advanceGuided(){const list=guidedList(),i=list.indexOf(current);if(i<list.length-1)openLesson(list[i+1].id);else finishSheet(gallery.find(a=>a.id===attemptToken));}
function resultSheet(){if(current.calibrationOnly)return calibrationResultSheet();if(!current.journey)return studioResultSheet();if(!ink.length)return;lastResult=E.evaluate(ink,current,inputType);saveAttempt(lastResult);const r=lastResult,final=current.completeWord,title=r.qualified?(final?'Your word, in your own hand.':'This step is complete.'):'Let’s try that once more.',coaching=r.qualified?(final?'You included the letter body and its required marks.':'Keep that movement in mind for the next step.'):t(r.reason),button=r.qualified?(final?'Frame my piece':'Continue to step '+(guidedPosition().index+2)):'Try again';openSheet('Your practice','<div class="guided-result"><div class="result-heading"><div class="result-icon">'+icon(r.qualified?'check':'leaf')+'</div><h2>'+title+'</h2></div><button class="textbtn" data-action="compare-overlay">Compare overlay</button><div class="comparison"><div><canvas id="model-result" width="350" height="300"></canvas><span>Model</span></div><div><canvas id="user-result" width="350" height="300"></canvas><span>Your writing</span></div></div><div class="coaching"><strong>'+(r.qualified?'Well practised':'One thing to adjust')+'</strong>'+coaching+'</div><details class="accuracy"><summary>Practice details</summary><p>Model similarity: '+r.score+'%. '+t('estimate')+'</p><p>'+t(mode)+' · '+(mode==='trace'?'Practised with the guide; this is not independent mastery.':mode==='copy'?'Copied from a visible example.':'Practised without a visible example.')+'</p></details><button class="btn wide" data-action="'+(r.qualified?'guided-next':'result-next')+'" '+(!r.qualified?'data-id="retry"':'')+'>'+button+icon('arrow')+'</button>'+(r.qualified&&final&&mode!=='recall'?'<button class="textbtn" style="width:100%" data-action="guided-mode" data-id="'+(mode==='trace'?'copy':'recall')+'">'+(mode==='trace'?'Try without the outline':'Try from memory')+'</button>':'<button class="textbtn" style="width:100%" data-action="close">Back to my page</button>')+'</div>');const points=[...current.strokes,...ink].flatMap(st=>st.points),reviewBounds={minX:Math.min(...points.map(p=>p.x))-65,maxX:Math.max(...points.map(p=>p.x))+65,minY:Math.min(...points.map(p=>p.y))-65,maxY:Math.max(...points.map(p=>p.y))+65};renderArtwork($('model-result'),{lessonId:current.id,strokes:[],reviewBounds},true);renderArtwork($('user-result'),{lessonId:current.id,strokes:ink,reviewBounds});appendCalibrationFeedback();}

document.addEventListener('click',e=>{const el=e.target.closest('[data-action]');if(!el||el.disabled)return;const a=el.dataset.action,id=el.dataset.id;switch(a){case'compare-overlay':openMovementOverlay();break;case'learning-continue':continuePractice();break;case'practice-status-help':practiceStatusHelp();break;
case'calibration-panel':calibrationOptions();calibrationPanel();break;case'calibration-toggle':calibrationOptions();if(calibrationOn){calibrationOn=false;calibrationMessage='Recording off. Existing captures are kept.';}else enableCalibration();closeSheet();render();calibrationPanel();break;case'calibration-lesson':calibrationOptions();if(!calibrationOn&&!enableCalibration())break;closeSheet();openLesson(id);switchMode('trace');break;case'calibration-export':exportCalibration();break;case'calibration-clear':confirmSheet('Delete only the locally saved test captures? Your practice gallery and progress will stay.','calibration-confirm-clear');break;case'calibration-confirm-clear':clearCalibration();break;case'calibration-flag':calibrationFlagPanel();break;case'calibration-label':labelCalibration(id);break;case'guided-word':closeSheet();openLesson(STUDIES[id].lessons[0].id);break;case'retry-strokes':strokeRetrySheet();break;case'retry-stroke':beginStrokeRetry(Number(id));break;case'cancel-retry':replaceIndex=null;inkCache=null;closeSheet();updatePractice();requestDraw();break;case'export-svg':exportSvg({lessonId:current.id,strokes:ink});break;case'gallery-svg':exportSvg(gallery[Number(el.dataset.index)]);break;case'piece-svg':if(pieceDraft)exportSvg(pieceDraft.art,pieceDraft.style);break;case'guided-start':closeSheet();resumeGuided();break;case'guided-tools':guidedTools();break;case'guided-replay':closeSheet();if(mode!=='watch')switchMode('watch');else{anim.index=0;anim.elapsed=0;anim.last=0;anim.playing=!settings.reduced;render();}break;case'guided-next':closeSheet();advanceGuided();break;case'guided-mode':closeSheet();switchMode(id);break;case'loop':closeSheet();navigate('loop');break;case'chapter3':closeSheet();ch3.open();navigate('chapter3');break;case'nav':closeSheet();if(id==='journey')studyId='bism';navigate(id);break;case'lesson':openLesson(id);break;case'script':id==='naskh'?navigate('journey'):coming(id);break;case'coming-naskh':closeSheet();navigate('journey');break;
case'theme':saveDraft();settings.dark=!settings.dark;saveSettings();render();break;
case'mode':switchMode(id);break;case'exit':if(current.calibrationOnly){closeSheet();navigate('home');calibrationPanel();break;}closeSheet();if(chapterReturn){chapterReturn=false;ch3.open();navigate('chapter3');break;}if(current.studyId)studyId=current.studyId;navigate(current.journey?'home':'course');break;case'close':closeSheet();break;
case'play':cancelAnimationFrame(raf);if(anim.index===current.strokes.length-1&&anim.elapsed>2000){anim.index=0;anim.elapsed=0;}anim.playing=!anim.playing;anim.last=0;updatePlayButton();if(anim.playing)raf=requestAnimationFrame(tick);break;
case'replay':cancelAnimationFrame(raf);anim.index=0;anim.elapsed=0;anim.last=0;anim.playing=!settings.reduced;updatePlayButton();updatePractice();renderPage();if(anim.playing)raf=requestAnimationFrame(tick);break;
case'step':anim.playing=false;cancelAnimationFrame(raf);anim.index=(anim.index+1)%current.strokes.length;anim.elapsed=settings.reduced?1700:0;updatePlayButton();updatePractice();renderPage();break;
case'undo':undoInk();break;
case'redo':redoInk();break;
case'pen':penSheet();break;case'guides':guidesSheet();break;case'more':moreSheet();break;case'free':free=id==='true';if(!free)nib={...current.pen};saveDraft();closeSheet();penSheet();break;
case'nib':if(free){nib.type=id;saveDraft();closeSheet();penSheet();}break;case'color':settings.color=id;saveSettings();saveDraft();closeSheet();penSheet();requestDraw();break;
case'check':resultSheet();break;case'result-next':closeSheet();if(id==='trycopy')switchMode('copy');else if(id==='tryrecall')switchMode('recall');else if(id==='finishPiece')finishSheet(gallery.find(a=>a.id===attemptToken));else if(id==='nextlesson'){const list=current.journey?studyFor(current).lessons:FOUNDATIONS,i=list.indexOf(current);i<list.length-1?openLesson(list[i+1].id):navigate(current.journey?'journey':'course');}else clearInk();break;
case'clear':if(ink.length)confirmSheet(t('clearask'),'confirm-clear');else closeSheet();break;case'confirm-clear':closeSheet();clearInk();break;
case'replay-mode':closeSheet();switchMode('watch');break;case'export-current':exportArt({lessonId:current.id,strokes:ink,date:new Date().toISOString()});break;case'export-art':{const art=gallery[Number(el.dataset.index)];if(LESSONS.find(l=>l.id===art.lessonId)?.completeWord)finishSheet(art);else exportArt(art);break;}
case'delete-art':confirmSheet(t('deleteask'),'confirm-delete',el.dataset.index);break;case'confirm-delete':gallery.splice(Number(el.dataset.index),1);write('gallery',gallery);closeSheet();render();break;
case'download-tests':download(new Blob([$('harf-regression-tests').textContent],{type:'text/javascript'}),'harf-regression-tests.cjs');break;case'download-lesson':{const l=structuredClone(current);l.schemaVersion='prototype-1.0';l.coordinateSystem={width:1000,height:1000,x:'right',y:'down',angles:'clockwise degrees from +x'};l.notice=reviewed(current)?'Bism movement model approved by a calligrapher as reported by the user. This prototype format is separate from the production lesson schema.':'New prototype movement geometry; review pending. This prototype format is separate from the production lesson schema.';download(new Blob([JSON.stringify(l,null,2)],{type:'application/json'}),'Khatti-'+l.id+'.json');break;}
case'preview-piece':{const l=activeStudy().lessons.at(-1);finishSheet({id:'model-preview',lessonId:l.id,date:new Date().toISOString(),qualified:true,modelPreview:true,strokes:l.strokes.map(st=>({points:st.points,nib:{...l.pen,...st.pen},input:'touch',color:'#263c34'}))});break;}case'study':closeSheet();selectStudy(id);break;case'basmala-reference':basmalaReference();break;case'word-notes':wordNotes();break;case'review-notes':reviewNotes();break;case'font-notes':{const credit=JSON.parse($('font-attribution').textContent);openSheet(t('fontCredits'),'<p>'+esc(credit.font)+'</p><p>'+esc(credit.copyright)+'</p><div class="font-license">'+esc(credit.license)+'</div>');break;}case'piece-paper':if(pieceDraft){pieceDraft.style.paper=id;const prior=pieceDraft;closeSheet();finishSheet({...prior.art,piece:prior.style});}break;case'save-piece':savePiece();break;case'device':{openSheet(t('device'),'<div class="device-tools">'+[320,360,390,412].map(w=>'<button data-action="device-width" data-id="'+w+'">'+w+' px</button>').join('')+'</div><iframe id="device-preview" class="device-frame" title="Khatti phone preview" style="width:390px" src="'+esc(location.href.split('?')[0])+'?preview=1"></iframe>');break;}case'device-width':if($('device-preview'))$('device-preview').style.width=id+'px';break;case'delete-all':confirmSheet(t('deleteallask'),'confirm-delete-all');break;case'confirm-delete-all':window.dispatchEvent(new Event('harf:clear-ayah-data'));try{localStorage.removeItem(CALIBRATION_KEY);calibrationRows=[];calibrationOn=false;calibrationSaved=true;calibrationLoadIssue=false;calibrationMessage='';calibrationSessionId=null;for(let i=localStorage.length-1;i>=0;i--){const k=localStorage.key(i);if(k.startsWith('harf.standalone.v1.')&&!k.endsWith('settings'))localStorage.removeItem(k);}}catch{}sessionWrites.clear();progress={};gallery=[];closeSheet();render();toast(t('deleted'));break;
}});
document.addEventListener('input',e=>{const k=e.target.dataset.setting;if(!k)return;if(k==='width'&&free){nib.width=Number(e.target.value);$('width-value').textContent=nib.width;saveDraft();}else if(k==='angle'&&free){nib.angle=Number(e.target.value);$('angle-value').textContent=nib.angle+'°';saveDraft();}else if(k==='opacity'){settings.opacity=Number(e.target.value)/100;$('opacity-value').textContent=e.target.value+'%';saveSettings();requestDraw();}});
document.addEventListener('change',e=>{if(e.target.id==='demo-speed'){anim.speed=Number(e.target.value);return;}const k=e.target.dataset.setting;if(!k||e.target.type!=='checkbox')return;if(k==='piece-frame'){if(pieceDraft){pieceDraft.style.frame=e.target.checked;paintPiece($('piece-canvas'),pieceDraft.art,pieceDraft.style);}return;}if(k==='pressure'){nib.pressure=e.target.checked;saveDraft();return;}if(k==='reveal'){reveal=e.target.checked;referenceSeen=referenceSeen||reveal;saveDraft();closeSheet();render();return;}settings[k]=e.target.checked;saveSettings();if(k==='reduced'&&settings.reduced){anim.playing=false;cancelAnimationFrame(raf);updatePlayButton();}saveDraft();requestDraw();});
document.addEventListener('keydown',e=>{if(screen!=='practice'||$('sheet').open||/INPUT|SELECT|TEXTAREA/.test(e.target.tagName))return;if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='z'){e.preventDefault();if(e.shiftKey)redoInk();else undoInk();}});
document.addEventListener('visibilitychange',()=>{if(document.hidden){if(active){active=null;pointer=null;requestDraw();}saveDraft();anim.playing=false;cancelAnimationFrame(raf);updatePlayButton();}});window.addEventListener('harf:flush-progress',()=>{if(!window.HarfProgressRestoring)saveDraft();});window.addEventListener('pagehide',saveDraft);
$('sheet').addEventListener('click',e=>{if(e.target===$('sheet')){const r=$('sheet').getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeSheet();}});
